def test_tytul_spojny_we_wszystkich_deklaracjach(self):
    html = self.client.get(self.artykul.get_absolute_url()).content.decode()
    h1 = re.search(r"<h1[^>]*>(.*?)</h1>", html, re.S).group(1).strip()
    dane = json.loads(re.search(r'application/ld\+json">(.*?)</script>', html, re.S).group(1))
