# Django - filtr szablonu nadający politykę rel automatycznie
from urllib.parse import urlparse
from django.utils.safestring import mark_safe
from bs4 import BeautifulSoup
from django import template

register = template.Library()

WLASNE_DOMENY = {"klient-a.pl", "www.klient-a.pl"}
# Źródła budujące wiarygodność - tu follow jest sygnałem pozytywnym
ZAUFANE_ZRODLA = {"gov.pl", "sejm.gov.pl", "nauka.gov.pl", "who.int"}


@register.filter
def polityka_linkow(html: str) -> str:
    """Uzupełnia rel i target dla odnośników wychodzących poza serwis."""
    zupa = BeautifulSoup(html, "html.parser")
    for link in zupa.find_all("a", href=True):
        host = (urlparse(link["href"]).hostname or "").lower()
        if not host or host in WLASNE_DOMENY:
            continue
        if any(host.endswith(zaufana) for zaufana in ZAUFANE_ZRODLA):
            link["rel"] = ["noopener"]          # źródło merytoryczne - follow zostaje
        else:
            link["rel"] = ["nofollow", "noopener"]
        link["target"] = "_blank"
    return mark_safe(str(zupa))

# Treści sponsorowane i tworzone przez użytkowników - osobne wartości rel
# <a href="..." rel="sponsored noopener">materiał partnera</a>
# <a href="..." rel="ugc nofollow noopener">link z komentarza</a>
